('清程极智', '—', 'ai', 'maas', false, 'A 轮', NULL, NULL, NULL, '2026-10', '{"name": "清程极智", "code": "—", "industry": "ai", "seg": "maas", "listed": false, "round": "A 轮", "valuation": null, "rev": null, "lastFundating": null, "desc": "清华高性能计算所系的国产算力系统软件公司，2023 年 12 月成立于北京海淀，2026 年 2 月完成清华大学科技成果作价入股。核心团队出自清华计算机系高性能计算研究所，郑纬民院士任首席顾问、翟季冬教授任首席科学家，创始人兼 CEO 汤雄超为清华计算机系博士，团队约 20 人、八成研发不足 30 岁。公司不造芯片、不做模型，做的是把国产芯片的硬件能力翻译成模型性能：赤兔推理引擎负责加速、AI Ping 负责评测与智能路由、八卦炉提供智能软件栈，三件产品覆盖 Token 的生产、调度与场景化使用，对外定位「一站式全链路 Token 解决方案」。", "latestTech": "已支持 18 家厂商 32 款 AI 芯片全场景适配；在 8 万卡规模实测训练万亿参数 MoE 模型，并以纯国产 CPU 跑通 DeepSeek-671B；在全国性国产芯片优化五项比武中拿下四项冠军；PD（预填充/解码）分离异构部署实测，国产显卡 Prefill 性价比超过 H 系列高端显卡。AI Ping 已接入 30 余家服务商、400 余个模型服务，官方口径可降成本 37%、提升吞吐 90%、降低延迟 20%。累计支撑超大型国产芯片系统 10 个以上，参与国家级项目 5 项以上，专利 30 项以上。", "tech": [{"date": "2026-10", "kind": "产品", "title": "发布全链路 Token 方案：赤兔引擎 · AI Ping · 八卦炉", "desc": "覆盖 Token 生产、调度、场景化使用三段，对标无问芯穹「前店后厂一中心」。"}, {"date": "2026-04", "kind": "技术", "title": "参与国家超算深圳中心国产 E 级超算「灵晟」AI 应用优化", "desc": "针对纯 CPU 架构完成算子开发、计算图调度等全栈优化。"}, {"date": "2026-03", "kind": "技术", "title": "PD 分离异构部署实测：国产显卡 Prefill 性价比超 H 系列"}, {"date": "2026-02", "kind": "公司", "title": "完成清华大学科技成果作价入股"}], "funding": [{"date": "2026-10", "round": "A轮", "amount": "未披露", "inv": "中国电信、瀚晖资本联合领投；星连资本追加；领阳投资、华胜天成、建信（北京）投资、直真科技、商汤科技、苏州毅鸣跟投"}, {"date": "2026-03", "round": "A+轮", "amount": "未披露", "inv": "清华大学资产管理公司"}, {"date": "2025", "round": "Pre-A+轮", "amount": "未披露", "inv": "中科创星、中金资本、考拉基金、联想创投、中关村科学城公司等"}], "investorsStructured": [{"date": "2026-10", "kind": "cvc", "name": "中国电信", "role": "lead", "round": "A轮", "note": "运营商产业资本，央企"}, {"date": "2026-10", "kind": "pe", "name": "瀚晖资本", "role": "lead", "round": "A轮"}, {"date": "2026-10", "kind": "vc", "name": "星连资本", "role": "follow", "round": "A轮", "note": "老股东追加"}, {"date": "2026-10", "kind": "cvc", "name": "商汤科技", "role": "follow", "round": "A轮"}, {"date": "2026-10", "kind": "cvc", "name": "华胜天成", "role": "follow", "round": "A轮"}, {"date": "2026-10", "kind": "vc", "name": "领阳投资", "role": "follow", "round": "A轮"}, {"date": "2026-10", "kind": "pe", "name": "建信（北京）投资", "role": "follow", "round": "A轮"}, {"date": "2026-10", "kind": "cvc", "name": "直真科技", "role": "follow", "round": "A轮"}, {"date": "2026-10", "kind": "vc", "name": "苏州毅鸣", "role": "follow", "round": "A轮"}, {"date": "2026-03", "kind": "other", "name": "清华大学资产管理公司", "role": "lead", "round": "A+轮", "note": "科技成果作价入股"}, {"date": "2025", "kind": "vc", "name": "中科创星", "role": "lead", "round": "Pre-A+轮"}, {"date": "2025", "kind": "vc", "name": "联想创投", "role": "follow", "round": "Pre-A+轮"}], "executives": [{"name": "汤雄超", "title": "创始人兼 CEO", "role": "management", "bio": "清华大学计算机系博士，因判断底层 AI 系统软件生态不完善而创业。"}, {"name": "郑纬民", "title": "首席顾问", "role": "board", "bio": "中国工程院院士，清华大学计算机系教授。"}, {"name": "翟季冬", "title": "首席科学家", "role": "board", "bio": "清华大学计算机系教授，曾带领清华超算团队夺得十余项世界冠军。"}, {"name": "师天麾", "title": "联合创始人", "role": "management", "bio": "信息学奥赛金牌保送清华计算机系，博士期间做万卡智算集群服务能力研究，中国信通院技术专家。"}], "execChanges": [], "lastFunding": "2026-10", "latestFunding": "2026-10 · A 轮（金额未披露），中国电信与瀚晖资本联合领投，星连资本追加，领阳投资、华胜天成、建信（北京）投资、直真科技、商汤科技、苏州毅鸣跟投。", "note": "与无问芯穹同源：清华系、异构调度、全链路 Token、不站队芯片厂商。差异在商业模式——清程走软件授权（约 20 人、不持算力池），无问芯穹走重资产运营（3.7 万 P 算力池 + 行业方案）。前者毛利安全、天花板低，后者天花板高、现金流重。"}'::jsonb),
('趋境科技', '—', 'ai', 'maas', false, 'A 轮', NULL, 50, NULL, '2026-07', '{"name": "趋境科技", "code": "—", "industry": "ai", "seg": "maas", "listed": false, "round": "A 轮", "valuation": 50, "rev": null, "desc": "清华「系统派」创业公司，2023 年 12 月注册于北京清华科技园，注册资本 566.43 万元，2025 年员工仅 29 人。创始人兼 CEO 艾智远为清华高性能计算所博士（师从武永卫），CTO 陈祥麟同样出自该所；郑纬民院士任首席科学顾问、武永卫教授任首席科学家、章明星副教授为联合发起人，已完成清华技术成果作价入股。董事长任旭阳为百度早期元老（曾牵头创立爱奇艺、一点资讯），总裁兼 CFO 武文洁曾任百度资本创始管理合伙人、携程 CFO。公司不做训练、只做推理优化，技术起点是开源异构推理框架 KTransformers，商业化载体为 ATaaS（Approaching.AI Token as a Service）平台，主打「少模型、深优化」。", "latestTech": "KTransformers 提出 CPU+GPU 异构 MoE 推理方案（GPU 负责注意力与主干、CPU 承担稀疏专家），论文入选 SOSP 2025，GitHub 超 1.7 万星，为全球首个边缘异构推理框架。2026 年推出异构协同 2.0：按计算强度对大模型任务做动态拆分，实现 CPU+GPU、GPU+GPU 跨层级异构推理，算力总成本降低 20% 以上。国产适配方面提出「国产 Prefill-Decode 异构协同」「高性能异构 KV Cache 转换」「异构算力计算池化」并已落地。截至 2026 年 7 月，ATaaS 平台日均处理 Token 近万亿，某头部万亿参数模型的高品质 Token 日产量稳定破万亿；自 2026 年春节以来单台算力 Token 生产效率提升 3 倍以上、总产能增长超 30 倍。", "tech": [{"date": "2026-07", "kind": "公司", "title": "华东总部落户杭州萧山，五年内建万卡级 AI Token 工厂"}, {"date": "2026-07", "kind": "生态", "title": "与商汤等近 20 家厂商发起「银河计划」，共建万卡级国产智算集群"}, {"date": "2026", "kind": "技术", "title": "异构协同 2.0：CPU+GPU 跨层级推理，算力总成本降 20%+"}, {"date": "2025", "kind": "技术", "title": "KTransformers 论文入选 SOSP 2025，GitHub 1.7 万星"}], "funding": [{"date": "2026-07", "round": "A轮", "amount": "未披露（半年累计超10亿元）", "inv": "河南投资集团汇融基金领投；真知资本、尚势资本、星连资本、上海国方创新、弘晖基金、华控基金、杭州福成超额跟投"}, {"date": "2026-05", "round": "Pre-A轮", "amount": "数亿元", "inv": "星连资本、华控基金联合领投；弘晖基金、天壕能源、尚势资本、天津仁爱弘盛、杭州福成跟投；高瓴创投加注"}, {"date": "2025-02", "round": "天使++轮", "amount": "未披露", "inv": "并行科技"}, {"date": "2025-02", "round": "天使+轮", "amount": "数千万元", "inv": "高瓴创投、Z基金领投；水木校友种子基金跟投；真知创投追投"}, {"date": "2024-08", "round": "天使轮", "amount": "未披露", "inv": "真知资本独家投资"}], "investorsStructured": [{"date": "2026-07", "kind": "gov", "name": "河南投资集团汇融基金", "role": "lead", "round": "A轮", "note": "河南国资，推动省内 60EFLOPS 算力消纳"}, {"date": "2026-05", "kind": "vc", "name": "星连资本", "role": "lead", "round": "Pre-A轮"}, {"date": "2026-05", "kind": "pe", "name": "华控基金", "role": "lead", "round": "Pre-A轮"}, {"date": "2026-05", "kind": "pe", "name": "弘晖基金", "role": "follow", "round": "Pre-A轮"}, {"date": "2026-05", "kind": "cvc", "name": "天壕能源", "role": "follow", "round": "Pre-A轮"}, {"date": "2026-05", "kind": "vc", "name": "尚势资本", "role": "follow", "round": "Pre-A轮"}, {"date": "2026-05", "kind": "vc", "name": "杭州福成", "role": "follow", "round": "Pre-A轮"}, {"date": "2025-02", "kind": "cvc", "name": "并行科技", "role": "strategic", "round": "天使++轮", "note": "算力服务商，上市公司"}, {"date": "2025-02", "kind": "vc", "name": "高瓴创投", "role": "lead", "round": "天使+轮"}, {"date": "2025-02", "kind": "vc", "name": "Z基金", "role": "lead", "round": "天使+轮"}, {"date": "2025-02", "kind": "vc", "name": "水木校友种子基金", "role": "follow", "round": "天使+轮"}, {"date": "2024-08", "kind": "vc", "name": "真知资本", "role": "lead", "round": "天使轮"}], "executives": [{"name": "艾智远", "title": "创始人兼 CEO", "role": "management", "bio": "清华大学高性能计算所博士，师从武永卫，研究方向为并行计算、分布式存储、AI 计算引擎优化；曾任深信服大数据、数字化、AI 应用等部门研发负责人。"}, {"name": "陈祥麟", "title": "CTO", "role": "management", "bio": "清华大学高性能计算所背景，负责推理系统与异构调度技术。"}, {"name": "任旭阳", "title": "董事长", "role": "board", "bio": "百度早期创业元老，曾牵头创立爱奇艺、一点资讯、海致、News Break。"}, {"name": "武文洁", "title": "总裁兼 CFO", "role": "management", "bio": "香港大学金融学博士、CFA，曾任百度资本创始管理合伙人、携程 CFO 兼首席战略官，主导蔚来、去哪儿等 50 余家企业投资并购。"}, {"name": "郑纬民", "title": "首席科学顾问", "role": "board", "bio": "中国工程院院士。"}, {"name": "武永卫", "title": "首席科学家", "role": "board", "bio": "清华大学计算机系教授。"}], "execChanges": [], "lastFunding": "2026-07", "latestFunding": "2026-07 · A 轮，河南投资集团汇融基金领投，半年内累计融资超 10 亿元，投后估值 50 亿元；A 轮距上一轮仅两个月，由投资方主动接洽的超额募资。", "note": "全赛道唯一公开声称「部分成熟业务已跨过成本线」的公司：2026 年 6 月单月收入超过 2025 年全年。以 29 人、50 亿估值对应 1.7 亿元/人的估值密度。客户为智谱 GLM、月之暗面 Kimi 等头部模型厂商，走「高品质 Token」（顶速、高稳定、长上下文）差异化路线，不与硅基流动争模型数量。"}'::jsonb),
('PPIO 派欧云', '—', 'ai', 'maas', false, 'B-2 轮', NULL, NULL, 7.7, '2026-05', '{"name": "PPIO 派欧云", "code": "—", "industry": "ai", "seg": "maas", "listed": false, "round": "B-2 轮", "valuation": null, "rev": 7.7, "desc": "独立边缘云计算服务商，2018 年由 PPTV 创始人姚欣与首席架构师王闻宇创立，开曼主体为派想未来集团（PPLabs Technology Limited），2019 年在开曼注册。区别于阿里云、腾讯云的重资产自建数据中心，公司以「蜂群思维」聚合全网闲置边缘算力节点，构建低成本、低延迟、可弹性调度的算力网络，业务分三层：IaaS 全球算力网络、MaaS 模型服务、AI 智能体基础设施（Agentic Infra，含 Agent 托管与沙箱）。按计算节点数计为中国最大算力网络，按 2025 年收入计为中国最大独立边缘云计算服务商，按日均 Token 消耗量计在独立 AI 云服务商中排名第一。", "latestTech": "自研推理优化可将大模型首字节延迟降低 95%、吞吐量提升 300%；引入 PD 分离，把 Prefill 与 Decode 独立调度并分别匹配最优 GPU；智能弹性调度基于历史数据与实时流量预测资源需求，以按量计费替代固定租赁，降低闲置成本。截至 2025 年底算力网络覆盖全球 1340 余个县市、4600 余个计算节点；截至 2026 年 4 月底注册开发者 57.4 万人；2026 年 4 月日均 Token 消耗 1.028 万亿次（2025 年 12 月为 2710 亿次，四个月约 3.8 倍）。", "tech": [{"date": "2026-09", "kind": "产品", "title": "Agent 沙箱支持接入 OpenAI Agents API，一键托管 Agent Harness"}, {"date": "2026-09", "kind": "生态", "title": "加入中国信通院「算力超银生态共建计划」"}, {"date": "2026-04", "kind": "运营", "title": "日均 Token 消耗达 1.028 万亿次，居独立 AI 云服务商首位"}, {"date": "2025", "kind": "财务", "title": "AI 云计算收入 1.19 亿元，同比增长逾 10 倍"}], "funding": [{"date": "2026-05", "round": "B-2轮", "amount": "3520万美元", "inv": "未完整披露"}, {"date": "2025", "round": "B+轮", "amount": "未披露", "inv": "蓝驰创投、创世伙伴、嘉实基金等"}, {"date": "2024", "round": "B轮", "amount": "未披露", "inv": "蓝驰创投、创世伙伴等"}], "investorsStructured": [{"date": "2026-05", "kind": "other", "name": "B-2 轮投资人", "role": "other", "round": "B-2轮", "note": "3520 万美元，投资方未完整披露"}, {"date": "2024", "kind": "vc", "name": "蓝驰创投", "role": "lead", "round": "B轮"}, {"date": "2024", "kind": "vc", "name": "创世伙伴", "role": "lead", "round": "B轮"}, {"date": "2024", "kind": "pe", "name": "嘉实基金", "role": "follow", "round": "B轮"}, {"date": "2023", "kind": "other", "name": "唐彬森", "role": "other", "round": "早期", "note": "元气森林创始人，个人投资"}, {"date": "2023", "kind": "other", "name": "王小川", "role": "other", "round": "早期", "note": "百川智能创始人，个人投资"}, {"date": "2023", "kind": "other", "name": "申元庆", "role": "other", "round": "早期", "note": "前微软 Azure 中国总裁，个人投资"}], "executives": [{"name": "姚欣", "title": "创始人兼 CEO", "role": "management", "bio": "华中科技大学计算机专业，2004 年休学创办 PPTV（峰值全球 4.5 亿用户），2018 年二次创业成立 PPIO。"}, {"name": "王闻宇", "title": "联合创始人兼首席架构师", "role": "management", "bio": "PPTV 联合创始团队成员，负责分布式算力网络架构。"}], "execChanges": [], "lastFunding": "2026-05", "latestFunding": "2026-05 · B-2 轮 3520 万美元；2026-06-10 以派想未来集团为主体二次递表港交所主板，工银国际、申万宏源香港联席保荐（首次递表于 2025-06-20，2025-12 失效）。", "note": "与无问芯穹、硅基流动同为「第三方 Token 工厂」，但底层资产不同：PPIO 是自己聚合的边缘节点网络（4600 节点），另两家主要是租用第三方智算中心。财务上已能看清全貌：2023–2025 营收 3.58/5.58/7.70 亿元，毛利率 17.7%/12.3%/9.4% 持续下滑，2025 年净亏 2.23 亿元。AI 云收入占比仅 15.5%，84.5% 仍来自毛利更低的边缘 CDN 与边缘云。"}'::jsonb)
